import {fresh,validate,apply,visible} from './model.mjs';
export function mount({container,state,search='',setState,signal,theme='dark'}){
 const root=container.shadowRoot||container.attachShadow({mode:'open'});let data,error='',disposed=false,showIgnored=false,editing=null;
 try{data=state===undefined?fresh():validate(state);}catch(e){error='Stored continuity data could not be opened. It has not been overwritten: '+e.message;data=null;}
 root.innerHTML=`<h2>Project continuity</h2><p>Source-attributed decisions, next actions, resources and blockers shared in Athena. Manual local notes, not an automatic chat capture or a verified completion detector. Do not paste credentials.</p><p id="notice" role="status"></p><form><label>Project<input name="project" required maxlength="200"></label><label>Kind<select name="kind"><option value="decision">Decision</option><option value="next-action">Next action</option><option value="resource">Resource</option><option value="blocker">Blocker</option></select></label><label>Note<textarea name="text" required maxlength="10000"></textarea></label><label>Source URL (optional HTTPS)<input name="source" type="url"></label><button type="submit">Save note</button><button type="button" id="cancel" hidden>Cancel revision</button></form><button id="ignored">Show ignored</button><button id="export">Export local continuity JSON</button><p>Notes remain in this browser. Export separately for backup; browser storage is not a remote backup. Sources are claims, not automatically trusted facts.</p><section id="entries" aria-label="Continuity entries"></section>`;
 const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('./style.css',import.meta.url).href;root.prepend(style);
 const $=s=>root.querySelector(s),form=$('form'),notice=$('#notice');notice.textContent=error||'Ready. No notes are sent to a provider.';
 function render(){if(disposed||!data)return;const list=$('#entries');list.replaceChildren();const rows=visible(data,search,showIgnored);for(const e of rows){const article=document.createElement('article'),head=document.createElement('h3');head.textContent=e.project+' · '+e.kind+(e.pinned?' · pinned':'')+(e.ignored?' · ignored':'');article.append(head);const rev=e.revisions.at(-1),body=document.createElement('pre');body.textContent=rev.text;article.append(body);if(rev.source){const link=document.createElement('a');link.href=rev.source;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Source: '+rev.source;article.append(link);}const details=document.createElement('details'),summary=document.createElement('summary'),history=document.createElement('pre');summary.textContent=e.revisions.length+' immutable revision(s) and policy history';history.textContent=JSON.stringify({revisions:e.revisions,history:e.history},null,2);details.append(summary,history);article.append(details);for(const [action,label] of [['revise','Revise'],['pin',e.pinned?'Unpin':'Pin'],['ignore',e.ignored?'Restore':'Ignore']]){const b=document.createElement('button');b.textContent=label;b.dataset.action=action;b.dataset.id=e.id;article.append(b);}list.append(article);}if(!rows.length)list.textContent='No matching entries. Missing evidence does not mean work is complete.';}
 function commit(action){try{const next=apply(data,action);data=next;const saved=setState?.(next);notice.textContent=saved===true?'Saved in this browser. Export a backup.':'Not saved to durable browser storage. Keep this page open and export the local draft.';render();return true;}catch(e){notice.textContent=e.message;return false;}}
 form.onsubmit=e=>{e.preventDefault();if(!data||disposed)return;const fields=form.elements;const action={type:editing?'revise':'add',id:editing||crypto.randomUUID(),project:fields.project.value,kind:fields.kind.value,text:fields.text.value,source:fields.source.value};if(commit(action)){editing=null;form.reset();fields.project.disabled=false;fields.kind.disabled=false;$('#cancel').hidden=true;}};
 $('#cancel').onclick=()=>{editing=null;form.reset();form.elements.project.disabled=false;form.elements.kind.disabled=false;$('#cancel').hidden=true;};
 $('#entries').onclick=e=>{const b=e.target.closest('button[data-action]');if(!b||disposed||!data)return;if(b.dataset.action==='revise'){const entry=data.entries.find(x=>x.id===b.dataset.id);editing=entry.id;form.elements.project.value=entry.project;form.elements.kind.value=entry.kind;form.elements.project.disabled=true;form.elements.kind.disabled=true;form.elements.text.value=entry.revisions.at(-1).text;form.elements.source.value=entry.revisions.at(-1).source;$('#cancel').hidden=false;form.elements.text.focus();}else commit({type:b.dataset.action,id:b.dataset.id});};
 $('#ignored').onclick=()=>{showIgnored=!showIgnored;$('#ignored').textContent=showIgnored?'Hide ignored':'Show ignored';render();};
 const urls=new Set();$('#export').onclick=()=>{if(!data||disposed)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));urls.add(url);const a=document.createElement('a');a.href=url;a.download='athena-continuity.json';a.click();};
 if(!data)for(const c of root.querySelectorAll('input,textarea,select,button'))c.disabled=true;
 function unmount(){if(disposed)return;disposed=true;for(const url of urls)URL.revokeObjectURL(url);root.replaceChildren();signal?.removeEventListener('abort',unmount);}
 function setTheme(t){container.dataset.theme=t==='light'?'light':'dark';}setTheme(theme);render();signal?.addEventListener('abort',unmount,{once:true});if(signal?.aborted)unmount();
 return {ready:!!data,unmount,setTheme,setSearch(q){search=String(q);render();}};
}
